using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetShipmentsAsync(string? statusFilter = null, string? searchTerm = null)
    {
        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrWhiteSpace(statusFilter))
            query = query.Where(s => s.Status == statusFilter);

        if (!string.IsNullOrWhiteSpace(searchTerm))
            query = query.Where(s =>
                s.TrackingNumber.Contains(searchTerm) ||
                s.Destination.Contains(searchTerm) ||
                s.RecipientName.Contains(searchTerm));

        return await query
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<ShipmentDto?> GetShipmentByIdAsync(int id)
    {
        var shipment = await db.Shipments.FindAsync(id);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var shipment = new Data.Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = dto.Origin,
            Destination = dto.Destination,
            RecipientName = dto.RecipientName,
            Status = "Pending",
            CreatedAt = DateTime.UtcNow,
            EstimatedDelivery = dto.EstimatedDelivery,
            Notes = dto.Notes
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus, string? notes = null)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new InvalidOperationException("Shipment not found");

        shipment.Status = newStatus.ToString();
        if (notes is not null)
            shipment.Notes = notes;
        if (newStatus == ShipmentStatus.Delivered)
            shipment.DeliveredAt = DateTime.UtcNow;

        await db.SaveChangesAsync();
        return ToDto(shipment);
    }

    private static ShipmentDto ToDto(Data.Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = Enum.TryParse<ShipmentStatus>(s.Status, out var status) ? status : ShipmentStatus.Pending,
        RecipientName = s.RecipientName,
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        DeliveredAt = s.DeliveredAt,
        Notes = s.Notes
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(10000, 99999)}";
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service, string? status, string? search) =>
            Results.Ok(await service.GetShipmentsAsync(status, search)));

        // Public endpoint — customers track without logging in
        app.MapGet("api/shipments/track/{trackingNumber}",
            async (IShipmentService service, string trackingNumber) =>
            {
                var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
                return shipment is null ? Results.NotFound() : Results.Ok(shipment);
            });

        group.MapGet("/{id:int}", async (IShipmentService service, int id) =>
        {
            var shipment = await service.GetShipmentByIdAsync(id);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        group.MapPost("/", async (IShipmentService service, ShipmentDto dto) =>
        {
            var created = await service.CreateShipmentAsync(dto);
            return Results.Created($"api/shipments/{created.Id}", created);
        });

        group.MapPut("/{id:int}/status", async (IShipmentService service, int id, StatusUpdateRequest request) =>
        {
            try
            {
                var updated = await service.UpdateShipmentStatusAsync(id, request.Status, request.Notes);
                return Results.Ok(updated);
            }
            catch (InvalidOperationException)
            {
                return Results.NotFound();
            }
        });
    }
}

public record StatusUpdateRequest(ShipmentStatus Status, string? Notes);

