+using ShipmentTracker.Client.Models;
+using ShipmentTracker.Client.Services;
+
+namespace ShipmentTracker.Endpoints;
+
+public static class ShipmentEndpoints
+{
+    public static void MapShipmentApi(this WebApplication app)
+    {
+        var group = app.MapGroup("api/shipments").RequireAuthorization();
+
+        group.MapGet("/", async (IShipmentService service, string? status, string? search) =>
+            Results.Ok(await service.GetShipmentsAsync(status, search)));
+
+        // Public endpoint — customers track without logging in
+        app.MapGet("api/shipments/track/{trackingNumber}",
+            async (IShipmentService service, string trackingNumber) =>
+            {
+                var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
+                return shipment is null ? Results.NotFound() : Results.Ok(shipment);
+            });
+
+        group.MapGet("/{id:int}", async (IShipmentService service, int id) =>
+        {
+            var shipment = await service.GetShipmentByIdAsync(id);
+            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
+        });
+
+        group.MapPost("/", async (IShipmentService service, ShipmentDto dto) =>
+        {
+            var created = await service.CreateShipmentAsync(dto);
+            return Results.Created($"api/shipments/{created.Id}", created);
+        });
+
+        group.MapPut("/{id:int}/status", async (IShipmentService service, int id, StatusUpdateRequest request) =>
+        {
+            try
+            {
+                var updated = await service.UpdateShipmentStatusAsync(id, request.Status, request.Notes);
+                return Results.Ok(updated);
+            }
+            catch (InvalidOperationException)
+            {
+                return Results.NotFound();
+            }
+        });
+    }
+}
+
+public record StatusUpdateRequest(ShipmentStatus Status, string? Notes);
+

